    public IAsyncEnumerable<JsonElement> InvokeServerStreamAsync(
        SunderRpcInvocationContext context,
        string serviceId,
        string methodId,
        JsonElement request,
        CancellationToken cancellationToken = default)
    {
        if (string.Equals(serviceId, "run-control", StringComparison.Ordinal) && string.Equals(methodId, "stream-chat", StringComparison.Ordinal))
        {
            return SerializeStream(_service1.StreamChatAsync(context, Deserialize<RunControlChatRequest>(request), cancellationToken), cancellationToken);
        }
        return ThrowStream(UnknownMethod(serviceId, methodId, "server-stream"), cancellationToken);
    }

    private static async ValueTask<JsonElement> SerializeUnaryAsync<T>(ValueTask<T> response)
        where T : notnull
        => JsonSerializer.SerializeToElement(await response.ConfigureAwait(false), JsonOptions);

    private static T Deserialize<T>(JsonElement value)
        where T : notnull
        => value.Deserialize<T>(JsonOptions)
           ?? throw new InvalidOperationException("A validated RPC request deserialized to null.");

    private static async IAsyncEnumerable<JsonElement> SerializeStream<T>(
        IAsyncEnumerable<T> source,
        [EnumeratorCancellation] CancellationToken cancellationToken)
        where T : notnull
    {
        await foreach (var item in source.WithCancellation(cancellationToken).ConfigureAwait(false))
        {
            yield return JsonSerializer.SerializeToElement(item, JsonOptions);
        }
    }

    private static async IAsyncEnumerable<JsonElement> ThrowStream(
        Exception exception,
        [EnumeratorCancellation] CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        await Task.CompletedTask;
        throw exception;
#pragma warning disable CS0162
        yield break;
#pragma warning restore CS0162
    }

    private static Exception UnknownMethod(string serviceId, string methodId, string kind)
        => new InvalidOperationException($"RPC provider adapter does not implement {kind} method '{serviceId}/{methodId}'.");
